import{_ as s,o as t,c as n,a4 as e}from"./chunks/framework.BBs01uty.js";const k=JSON.parse('{"title":"npm / yarn / pnpm 包管理器对比","description":"","frontmatter":{"title":"npm / yarn / pnpm 包管理器对比","date":"2026-08-06T00:00:00.000Z"},"headers":[],"relativePath":"engineering/package-managers.md","filePath":"engineering/package-managers.md"}'),p={name:"engineering/package-managers.md"};function i(d,a,o,l,r,h){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="npm-yarn-pnpm-包管理器对比" tabindex="-1">npm / yarn / pnpm 包管理器对比 <a class="header-anchor" href="#npm-yarn-pnpm-包管理器对比" aria-label="Permalink to &quot;npm / yarn / pnpm 包管理器对比&quot;">​</a></h1><p>npm、yarn、pnpm 是前端最主流的三个包管理器，核心差异在于 <strong>node_modules 的组织结构</strong>。</p><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>npm 是默认、yarn 是速度革命、pnpm 是结构革命</strong>——pnpm 用&quot;全局 store + 硬链接 + 严格依赖树&quot;同时解决磁盘占用和幽灵依赖，是 Monorepo 时代的主流选择。</p><h2 id="发展史-为什么会有-yarn-和-pnpm" tabindex="-1">发展史：为什么会有 yarn 和 pnpm <a class="header-anchor" href="#发展史-为什么会有-yarn-和-pnpm" aria-label="Permalink to &quot;发展史：为什么会有 yarn 和 pnpm&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm 2（2011）     嵌套 node_modules → 目录深、安装慢、Windows 路径超长</span></span>
<span class="line"><span>npm 3+（2015）    扁平化 node_modules → 快，但引入幽灵依赖</span></span>
<span class="line"><span>yarn 1（2016）    并行安装 + 缓存 + yarn.lock → 更快更稳，但仍是扁平结构</span></span>
<span class="line"><span>pnpm（2017）      全局 store + 硬链接 + 严格树 → 磁盘省、无幽灵依赖</span></span></code></pre></div><p>每次&quot;革命&quot;都是解决前一代的痛点：</p><table tabindex="0"><thead><tr><th>痛点</th><th>解法</th></tr></thead><tbody><tr><td>npm 2 嵌套太深太慢</td><td>npm 3+ / yarn 扁平化</td></tr><tr><td>扁平化的幽灵依赖</td><td>pnpm 严格依赖树</td></tr><tr><td>多项目重复装依赖浪费磁盘</td><td>pnpm 全局 store 硬链接</td></tr></tbody></table><h2 id="前置知识-node-模块解析规则" tabindex="-1">前置知识：Node 模块解析规则 <a class="header-anchor" href="#前置知识-node-模块解析规则" aria-label="Permalink to &quot;前置知识：Node 模块解析规则&quot;">​</a></h2><p>理解三者差异的钥匙是 Node 的解析规则：<strong>从当前文件目录开始，逐层向上找 <code>node_modules</code>，找到就停止</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/src/app.js 里 import &#39;lodash&#39;</span></span>
<span class="line"><span>查找顺序：/src/node_modules → /node_modules → /../node_modules ...</span></span></code></pre></div><p>这个规则决定了：<strong>只要某个包出现在你能&quot;看到&quot;的某一层 node_modules 里，你就能用到它</strong>——这就是扁平化产生幽灵依赖的根本原因。</p><h2 id="三种-node-modules-结构" tabindex="-1">三种 node_modules 结构 <a class="header-anchor" href="#三种-node-modules-结构" aria-label="Permalink to &quot;三种 node_modules 结构&quot;">​</a></h2><h3 id="_1-嵌套结构-npm-2" tabindex="-1">1. 嵌套结构（npm 2） <a class="header-anchor" href="#_1-嵌套结构-npm-2" aria-label="Permalink to &quot;1. 嵌套结构（npm 2）&quot;">​</a></h3><p>每个包在自己的 node_modules 里装自己的依赖，层层嵌套：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node_modules/</span></span>
<span class="line"><span>└── a/</span></span>
<span class="line"><span>    ├── index.js</span></span>
<span class="line"><span>    └── node_modules/</span></span>
<span class="line"><span>        └── b/</span></span>
<span class="line"><span>            └── node_modules/</span></span>
<span class="line"><span>                └── c/</span></span></code></pre></div><p>问题：目录深（Windows 路径超长）、同一个包被重复安装 N 份、安装慢。</p><h3 id="_2-扁平结构-npm-3-yarn-1" tabindex="-1">2. 扁平结构（npm 3+ / yarn 1） <a class="header-anchor" href="#_2-扁平结构-npm-3-yarn-1" aria-label="Permalink to &quot;2. 扁平结构（npm 3+ / yarn 1）&quot;">​</a></h3><p>所有依赖（包括依赖的依赖）尽量提升到顶层：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node_modules/</span></span>
<span class="line"><span>├── react        ← 你的直接依赖</span></span>
<span class="line"><span>├── lodash       ← 被 a 依赖，但提升到了顶层（幽灵依赖温床）</span></span>
<span class="line"><span>├── a/</span></span>
<span class="line"><span>└── b/</span></span></code></pre></div><p>问题：<strong>幽灵依赖</strong>——你代码里能 <code>import</code> 到的包，可能不在你的 <code>package.json</code> 里。</p><h3 id="_3-严格树结构-pnpm" tabindex="-1">3. 严格树结构（pnpm） <a class="header-anchor" href="#_3-严格树结构-pnpm" aria-label="Permalink to &quot;3. 严格树结构（pnpm）&quot;">​</a></h3><p>顶层只有直接依赖（软链接），真实文件都放在 <code>.pnpm</code> 虚拟商店里：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node_modules/</span></span>
<span class="line"><span>├── react -&gt; .pnpm/react@18.2.0/node_modules/react    ← 软链接</span></span>
<span class="line"><span>├── a -&gt; .pnpm/a@1.0.0/node_modules/a                 ← 软链接</span></span>
<span class="line"><span>└── .pnpm/</span></span>
<span class="line"><span>    ├── react@18.2.0/node_modules/react               ← 真实文件（硬链接自全局 store）</span></span>
<span class="line"><span>    └── a@1.0.0/node_modules/</span></span>
<span class="line"><span>        ├── a</span></span>
<span class="line"><span>        └── lodash -&gt; ../../lodash@4.17.21/node_modules/lodash</span></span></code></pre></div><h2 id="术语详解" tabindex="-1">术语详解 <a class="header-anchor" href="#术语详解" aria-label="Permalink to &quot;术语详解&quot;">​</a></h2><h3 id="硬链接-hard-link" tabindex="-1">硬链接（Hard Link） <a class="header-anchor" href="#硬链接-hard-link" aria-label="Permalink to &quot;硬链接（Hard Link）&quot;">​</a></h3><p><strong>同一份数据的多个名字</strong>。磁盘上数据只存一份（inode），可以有多个文件名指向它。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hello&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> c.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 数据 hello，链接计数 = 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> c.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 计数 = 2，a.txt 和 c.txt 是同一份数据的两个名字</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> c.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # 计数 = 1，数据还在！a.txt 照样能读</span></span></code></pre></div><ul><li>修改任意一个名字的内容，所有名字都变（本来就是同一份数据）</li><li>删除只是&quot;摘掉一个名字&quot;（计数 -1），<strong>计数归 0 数据才真正释放</strong></li><li>没有&quot;本体 vs 引用&quot;之分，所有名字地位平等</li><li>只能在同磁盘分区内创建，不能对目录创建</li></ul><p><strong>pnpm 用它做什么</strong>：所有项目装的依赖都硬链接自全局 store（<code>pnpm store path</code>）里的同一份数据——100 个项目装同一个 React，磁盘只占一份。</p><h3 id="软链接-symbolic-link" tabindex="-1">软链接（Symbolic Link） <a class="header-anchor" href="#软链接-symbolic-link" aria-label="Permalink to &quot;软链接（Symbolic Link）&quot;">​</a></h3><p><strong>路径的快捷方式</strong>。软链接自己是一个独立小文件，内容就是一行目标路径字符串。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> c.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shortcut</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # shortcut 内容 = &quot;c.txt&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> c.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # shortcut 断链 → cat shortcut 报 No such file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shortcut</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 目标无感</span></span></code></pre></div><ul><li>依赖目标存在，目标被删就悬空（broken）</li><li>可以跨磁盘、可以指向目录</li></ul><p><strong>pnpm 用它做什么</strong>：项目顶层 <code>node_modules</code> 里的每个包都是一个软链接，指向 <code>.pnpm</code> 里的真实文件。</p><table tabindex="0"><thead><tr><th></th><th>硬链接</th><th>软链接</th></tr></thead><tbody><tr><td>本质</td><td>数据的另一个名字</td><td>路径的引用</td></tr><tr><td>删除链接本身</td><td>目标无感（计数 -1）</td><td>目标无感</td></tr><tr><td>删除目标</td><td>只要还有名字指向，数据就在</td><td>链接断链</td></tr><tr><td>跨分区</td><td>不行</td><td>可以</td></tr><tr><td>指向目录</td><td>不行</td><td>可以</td></tr></tbody></table><h3 id="幽灵依赖-phantom-dependency" tabindex="-1">幽灵依赖（Phantom Dependency） <a class="header-anchor" href="#幽灵依赖-phantom-dependency" aria-label="Permalink to &quot;幽灵依赖（Phantom Dependency）&quot;">​</a></h3><p><strong>没在 <code>package.json</code> 里声明，却能被代码 import 到的依赖</strong>。</p><p>产生原因：扁平化结构把&quot;依赖的依赖&quot;也提升到了顶层 node_modules，而 Node 解析规则又允许从顶层找到它。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// package.json 里没装 lodash，但代码能跑：</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;lodash&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // lodash 是 a 包的依赖，被扁平化提升到了顶层</span></span></code></pre></div><p>危害：</p><ul><li>某天 <code>a</code> 升级后不再依赖 lodash → <strong>你的代码突然崩了，但你什么都没改</strong></li><li>换环境（CI / 新同事）安装布局不同 → 本地好、线上炸</li><li>两个包依赖同一库的不同版本，扁平化只能提升一个 → 版本错乱</li></ul><p>pnpm 的严格树结构从根源上杜绝：顶层只有你声明的依赖，lodash 藏在 <code>.pnpm</code> 里，你的代码向上找两层都找不到，<strong>直接报错</strong>，逼你把依赖写进 <code>package.json</code>。</p><h3 id="锁文件-lockfile" tabindex="-1">锁文件（Lockfile） <a class="header-anchor" href="#锁文件-lockfile" aria-label="Permalink to &quot;锁文件（Lockfile）&quot;">​</a></h3><p>记录<strong>实际安装的精确版本和依赖关系</strong>的文件，保证&quot;任何人、任何时候安装，结果完全一致&quot;。</p><table tabindex="0"><thead><tr><th>工具</th><th>锁文件</th></tr></thead><tbody><tr><td>npm</td><td><code>package-lock.json</code></td></tr><tr><td>yarn</td><td><code>yarn.lock</code></td></tr><tr><td>pnpm</td><td><code>pnpm-lock.yaml</code></td></tr></tbody></table><p>必须提交到 Git：不提交的话，同事/CI 安装时可能解析到不同的次版本，出现&quot;我这边好的你那边炸&quot;。</p><h2 id="pnpm-的完整安装流程" tabindex="-1">pnpm 的完整安装流程 <a class="header-anchor" href="#pnpm-的完整安装流程" aria-label="Permalink to &quot;pnpm 的完整安装流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm install</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─ 1. 解析依赖 → 生成依赖图</span></span>
<span class="line"><span>    ├─ 2. 检查全局 store 是否有缓存</span></span>
<span class="line"><span>    │     ├─ 有 → 直接硬链接，跳过下载</span></span>
<span class="line"><span>    │     └─ 没有 → 下载到 store，再硬链接</span></span>
<span class="line"><span>    ├─ 3. 在 node_modules/.pnpm 建立真实文件（硬链接）</span></span>
<span class="line"><span>    └─ 4. 在顶层 node_modules 建立软链接（只有直接依赖）</span></span></code></pre></div><p>三层结构对应三个职责：</p><table tabindex="0"><thead><tr><th>层</th><th>机制</th><th>职责</th></tr></thead><tbody><tr><td>全局 store</td><td>真实数据唯一副本</td><td>省磁盘</td></tr><tr><td><code>.pnpm</code> 虚拟商店</td><td>硬链接自 store</td><td>版本隔离（每个版本独立目录）</td></tr><tr><td>顶层 node_modules</td><td>软链接</td><td>只暴露直接依赖，杜绝幽灵依赖</td></tr></tbody></table><h2 id="三工具对比" tabindex="-1">三工具对比 <a class="header-anchor" href="#三工具对比" aria-label="Permalink to &quot;三工具对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>npm</th><th>yarn 1</th><th>pnpm</th></tr></thead><tbody><tr><td><strong>node_modules 结构</strong></td><td>扁平</td><td>扁平</td><td>严格树</td></tr><tr><td><strong>幽灵依赖</strong></td><td>有</td><td>有</td><td>无</td></tr><tr><td><strong>磁盘占用</strong></td><td>每个项目一份</td><td>每个项目一份</td><td>全局 store 一份（硬链接）</td></tr><tr><td><strong>安装速度</strong></td><td>串行、慢</td><td>并行、缓存</td><td>并行 + 硬链接，最快</td></tr><tr><td><strong>锁文件</strong></td><td>package-lock.json</td><td>yarn.lock</td><td>pnpm-lock.yaml</td></tr><tr><td><strong>Monorepo 支持</strong></td><td>workspace（基础）</td><td>workspace（基础）</td><td>workspace + 严格隔离，最完善</td></tr><tr><td><strong>社区生态</strong></td><td>默认标配</td><td>较成熟</td><td>快速增长，主流新项目选择</td></tr></tbody></table><h2 id="monorepo-下的差异" tabindex="-1">Monorepo 下的差异 <a class="header-anchor" href="#monorepo-下的差异" aria-label="Permalink to &quot;Monorepo 下的差异&quot;">​</a></h2><h3 id="workspace-协议-workspace" tabindex="-1">workspace 协议（<code>workspace:*</code>） <a class="header-anchor" href="#workspace-协议-workspace" aria-label="Permalink to &quot;workspace 协议（\`workspace:*\`）&quot;">​</a></h3><p>Monorepo 里包之间互相依赖，用 <code>workspace:*</code> 声明&quot;引用仓库内的这个包&quot;：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// packages/app/package.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@my-org/ui&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workspace:*&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 指向仓库内的 ui 包，不是 npm 上的版本</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>解决：本地引用即时生效、无需发布 npm 就能联调、版本统一管理。</p><h3 id="增量构建" tabindex="-1">增量构建 <a class="header-anchor" href="#增量构建" aria-label="Permalink to &quot;增量构建&quot;">​</a></h3><p>Monorepo 里只构建&quot;受影响的包&quot;（依赖链上的包），需要工具支持：pnpm 的 <code>--filter</code>、Turborepo 的依赖图分析 + 远程缓存。</p><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐</th></tr></thead><tbody><tr><td>新项目、Monorepo</td><td><strong>pnpm</strong>（严格依赖 + 省磁盘 + workspace 完善）</td></tr><tr><td>老项目迁移成本敏感</td><td>npm（零迁移，生态默认）</td></tr><tr><td>团队习惯 yarn 且无 Monorepo 需求</td><td>yarn classic（够用）</td></tr><tr><td>企业级超大型仓库</td><td>pnpm + Turborepo / Nx</td></tr></tbody></table><h2 id="面试速答" tabindex="-1">面试速答 <a class="header-anchor" href="#面试速答" aria-label="Permalink to &quot;面试速答&quot;">​</a></h2><ul><li><strong>硬链接 vs 软链接</strong>：硬链接是&quot;数据的另一个名字&quot;（计数归零才删），软链接是&quot;路径的快捷方式&quot;（目标没了就断）</li><li><strong>幽灵依赖是什么</strong>：没声明却能 import 的依赖，扁平化的产物，换依赖就崩</li><li><strong>pnpm 本质区别</strong>：全局 store 硬链接省磁盘 + 严格树杜绝幽灵依赖 + workspace 协议支持 Monorepo</li><li><strong>为什么 pnpm 没有幽灵依赖</strong>：顶层 node_modules 只有直接依赖的软链接，Node 向上解析找不到没声明的包</li><li><strong>lockfile 作用</strong>：锁定精确版本，保证环境一致，必须提交 Git</li></ul>`,64)])])}const g=s(p,[["render",i]]);export{k as __pageData,g as default};
